/* EVO Eventos — protótipo visual. Somente navegação de telas; nenhuma API de negócio. */
const icon = (name, extra = '') => `<i class="ph ph-${name} ${extra}" aria-hidden="true"></i>`;
const picture = 'assets/quadra-evo.png';
const link = (view) => `?view=${view}`;
const demo = 'data-demo="Este é um controle de design. Nenhuma informação será enviada ou salva."';
const events = [
  { id:'open', title:'EVO Open — Duplas & Conexões', day:'28', month:'NOV', date:'Sáb, 28 de novembro', time:'08h às 14h', place:'EVO Hípica · Brasília', category:'Torneio', art:'', label:'EVO OPEN', top:'JOGUE. CONECTE. CELEBRE.', price:'180', cents:'00', tag:'Inscrições abertas', status:'green', availability:'2 vagas disponíveis', available:2 },
  { id:'clinic', title:'Clínica de saque & devolução', day:'29', month:'NOV', date:'Dom, 29 de novembro', time:'09h às 12h', place:'EVO Lago Sul · Brasília', category:'Clínica', art:'art-clinic', label:'ELEVE<br>SEU JOGO.', top:'CLÍNICA EVO', price:'90', cents:'00', tag:'Para todos os níveis', status:'', availability:'6 vagas disponíveis', available:6 },
  { id:'sunset', title:'Sunset na quadra', day:'05', month:'DEZ', date:'Sáb, 5 de dezembro', time:'16h às 20h', place:'EVO Noroeste · Brasília', category:'Experiência', art:'art-sunset', label:'SUNSET<br>NA QUADRA.', top:'O MELHOR DO FIM DE TARDE', price:'149', cents:'00', tag:'Lista de espera', status:'purple', availability:'Vagas esgotadas · entre na lista', available:0 }
];
const screenNames = {catalogo:'Eventos',evento:'Detalhe do evento',inscricao:'Inscrição · seus dados',pagamento:'Inscrição · pagamento',espera:'Lista de espera',minhas:'Minhas inscrições',admin:'Admin · eventos',participantes:'Admin · participantes',editor:'Admin · editar evento'};
const current = new URLSearchParams(window.location.search).get('view') || 'catalogo';
const view = Object.hasOwn(screenNames,current) ? current : 'catalogo';

function brand(admin=false){return `<a class="brand" href="${link(admin?'admin':'catalogo')}" aria-label="EVO Eventos — ${admin?'administração':'início'}"><span class="brand-mark">EVO</span><span class="brand-divider"></span><span class="brand-name">${admin?'GESTÃO':'EVENTOS'}</span></a>`;}
function preview(){return `<div class="preview-bar"><span class="preview-tag">Prévia de design</span><span class="preview-desc">Conteúdo ilustrativo · Sem inscrições ou pagamentos</span><button type="button" id="preview-toggle" aria-controls="preview-menu" aria-expanded="false">Telas da prévia ${icon('squares-four')}</button></div><nav class="preview-menu" id="preview-menu" aria-label="Telas da prévia" hidden><p>Explore o design das telas.<br>Todos os dados são fictícios.</p>${Object.entries(screenNames).map(([key,name])=>`<a href="${link(key)}" ${key===view?'aria-current="page"':''}>${icon(key==='catalogo'?'grid-four':key==='admin'?'squares-four':key==='editor'?'pencil-simple':key==='participantes'?'users':key==='minhas'?'ticket':key==='espera'?'hourglass-medium':key==='pagamento'?'credit-card':key==='inscricao'?'user-circle':'calendar-blank')}${name}</a>`).join('')}</nav>`;}
function header(){return `${preview()}<header class="site-header"><div class="container header-inner">${brand()}<nav class="main-nav" aria-label="Navegação principal"><a href="${link('catalogo')}" class="${view==='catalogo'||view==='evento'?'active':''}">Explorar eventos</a><a href="${link('minhas')}" class="${view==='minhas'?'active':''}">Minhas inscrições</a></nav><div class="header-actions"><a class="admin-link" href="${link('admin')}" aria-label="Ver design da administração">${icon('squares-four')}<span>Administração</span></a><a class="avatar" href="${link('minhas')}" aria-label="Ver inscrições da participante ilustrativa Marina Oliveira">MO</a></div></div></header>`;}
function footer(){return `<footer class="site-footer"><div class="container footer-inner"><div class="footer-brand"><a href="${link('catalogo')}" class="brand-mark" aria-label="EVO Eventos início">EVO</a><span>CLUB TENNIS ACADEMY<br>Dentro e fora das quadras.</span></div><div class="footer-links"><a href="${link('catalogo')}">Eventos</a><a href="${link('minhas')}">Minhas inscrições</a><a href="${link('admin')}">Administração</a></div><span class="footer-copy">© 2026 EVO Club · Prévia visual</span></div></footer>`;}
function eventArt(event,small=false){return `<div class="event-art ${event.art}"><img src="${picture}" alt="Quadra de tênis ilustrativa ao pôr do sol" ${small?'':'loading="lazy"'}><span class="pill ${event.status==='purple'?'purple':''}">${event.tag}</span><div class="art-label"><small>${event.top}</small>${event.label}</div><div class="date-tile"><strong>${event.day}</strong><span>${event.month}</span></div></div>`;}
function eventCard(event,small=false){const destination=event.id==='clinic'?'#':link(event.available?'evento':'espera');const previewOnly=event.id==='clinic'?'data-demo="O cartão da clínica demonstra outra categoria. O detalhe navegável desta prévia é o EVO Open."':'';return `<article class="event-card">${eventArt(event,small)}<div class="event-body"><div class="event-meta">${icon('calendar-blank')}${event.date} · ${event.time.split(' às ')[0]}</div><h3><a href="${destination}" ${previewOnly}>${event.title}</a></h3><div class="event-place">${icon('map-pin')}${event.place}</div><div class="event-bottom"><div class="price"><small>Por participante</small><strong>R$ ${event.price}<span>,${event.cents}</span></strong></div><a class="btn ${event.available?'ghost':'secondary'} small" href="${destination}" ${previewOnly}>${event.available?'Ver evento':'Lista de espera'}</a></div><div class="capacity ${event.available?'':'purple'}">${icon(event.available?'users':'hourglass-medium')}${event.availability}</div></div></article>`;}
function breadcrumbs(items){return `<nav class="breadcrumbs" aria-label="Caminho da página"><a href="${link('catalogo')}">Eventos</a>${items.map(item=>`${icon('caret-right')}${item.href?`<a href="${link(item.href)}">${item.text}</a>`:`<span aria-current="page">${item.text}</span>`}`).join('')}</nav>`;}
function catalog(){return `${header()}<main id="conteudo" class="container view-enter"><section class="hero" aria-labelledby="hero-title"><img class="hero-image" src="${picture}" alt="Quadra verde de tênis em um fim de tarde, imagem ilustrativa"><div class="hero-copy"><div class="hero-kicker">${icon('tennis-ball')} O jogo continua além da quadra</div><h1 id="hero-title">Viva o próximo<br><em>momento EVO.</em></h1><p>Encontros, desafios e boas histórias.<br>Encontre sua próxima experiência com a gente.</p><div class="hero-cta"><a href="#eventos" class="btn primary">Explorar eventos</a><a href="${link('minhas')}" class="text-link">Minhas inscrições</a></div></div><div class="hero-date"><strong>28</strong><span>NOVEMBRO</span></div><div class="hero-caption"><div><strong>EVO Open — Duplas & Conexões</strong><span>EVO Hípica · Brasília</span></div>${icon('tennis-ball')}</div></section><div class="brand-strip"><span class="feature">${icon('tennis-ball')}Esporte que conecta</span><span class="feature">${icon('users-three')}Experiências para a comunidade EVO</span><span class="feature">${icon('map-pin')}Nas nossas unidades</span><span class="feature">See you on court.</span></div><section id="eventos" aria-labelledby="eventos-title"><div class="section-head"><div><span class="eyebrow section-eyebrow">A agenda é sua</span><h2 id="eventos-title">Encontre seu próximo encontro.</h2></div><p class="quiet">Mais jogo. Mais conexões. Mais EVO.</p></div><div class="filters"><div class="tabs" aria-label="Categorias ilustrativas"><button type="button" class="tab active" ${demo}>Todos os eventos</button><button type="button" class="tab" ${demo}>${icon('trophy')}Torneios</button><button type="button" class="tab" ${demo}>${icon('tennis-ball')}Clínicas</button><button type="button" class="tab" ${demo}>${icon('sparkle')}Experiências</button></div><div class="filter-group"><button type="button" class="filter-box" ${demo}>${icon('map-pin')}Todas as unidades ${icon('caret-down')}</button><button type="button" class="filter-box" ${demo}>${icon('calendar-blank')}Próximas datas ${icon('caret-down')}</button></div></div><p class="results-label">3 experiências para viver com a EVO · Agenda ilustrativa</p><div class="event-grid">${events.map(event=>eventCard(event)).join('')}</div></section><aside class="about-banner">${icon('tennis-ball')}<div><h3>A EVO também acontece fora das quadras.</h3><p>Um bom encontro pode ser o começo de muitas histórias. Faça parte das nossas.</p></div><a href="${link('minhas')}" class="btn ghost small">Ver minhas inscrições</a></aside></main>${footer()}`;}
function detail(){return `${header()}<main id="conteudo" class="container detail-page view-enter">${breadcrumbs([{text:'EVO Open — Duplas & Conexões'}])}<section class="detail-hero"><img src="${picture}" alt="Quadra de tênis ilustrativa para a capa do EVO Open"><div class="detail-overlay"><span class="pill">${icon('trophy')} Torneio de duplas</span><h1>EVO Open<br>Duplas & Conexões</h1><p>Um sábado para jogar, conhecer e celebrar.</p></div></section><div class="detail-grid"><div><section class="detail-facts" aria-label="Informações do evento"><div class="fact">${icon('calendar-blank')}<div><strong>Sábado, 28 de novembro</strong><span>2026 · Das 08h às 14h</span></div></div><div class="fact">${icon('map-pin')}<div><strong>EVO Hípica</strong><span>Brasília, Distrito Federal</span></div></div><div class="fact">${icon('tennis-ball')}<div><strong>Todos os níveis são bem-vindos</strong><span>Duplas, boas trocas e muita conexão</span></div></div><div class="fact">${icon('users')}<div><strong>48 participantes</strong><span>Uma experiência para a comunidade EVO</span></div></div></section><section class="prose"><h2>Mais que um torneio. Um encontro.</h2><p>Prepare a raquete e venha viver um sábado diferente. O EVO Open reúne a nossa comunidade em um torneio de duplas que combina bons jogos, novas parcerias e aquele clima que só a EVO tem.</p><p>Não precisa chegar com dupla formada: a proposta é se conectar. Nossa equipe organiza os jogos para que todo mundo aproveite a experiência, do primeiro saque ao último ponto.</p><h2>O que faz parte da experiência</h2><div class="inclusions"><span>${icon('check-circle')}Jogos de duplas organizados</span><span>${icon('check-circle')}Welcome coffee</span><span>${icon('check-circle')}Acompanhamento da equipe EVO</span><span>${icon('check-circle')}Premiação e encontro final</span></div><h2>Como vai ser o dia</h2><div class="schedule"><div><strong>08h00</strong><span>Recepção e welcome coffee</span></div><div><strong>08h30</strong><span>Boas-vindas e organização das duplas</span></div><div><strong>09h00</strong><span>Hora de entrar em quadra</span></div><div><strong>13h00</strong><span>Premiação, conexões e celebração</span></div></div><h2>Antes de entrar em quadra</h2><p>Traga sua raquete, roupa confortável e garrafa de água. Em caso de mudança na programação, os participantes serão informados pela equipe EVO.</p><p class="quiet">Evento, datas, local e condições apresentados apenas como exemplo de design.</p></section></div><aside class="booking-card"><span class="eyebrow">Sua próxima experiência</span><div class="booking-price"><small>R$</small> 180<small>,00</small></div><p>Valor por participante.<br>Todos os momentos do evento incluídos.</p><div class="booking-capacity">${icon('users')}2 de 48 vagas disponíveis</div><a href="${link('inscricao')}" class="btn primary full">Quero participar</a><div class="booking-safe">${icon('user-circle')}Com sua conta EVO existente</div><div class="booking-note">${icon('info')}<span>A inscrição será confirmada após a verificação do pagamento.</span></div></aside></div></main><div class="mobile-booking"><div class="price"><small>2 vagas · valor por pessoa</small><strong>R$ 180<span>,00</span></strong></div><a href="${link('inscricao')}" class="btn primary">Quero participar</a></div>${footer()}`;}
function summary(){return `<aside><div class="summary-card"><img src="${picture}" alt="Capa ilustrativa do EVO Open"><div class="summary-body"><span class="eyebrow">Sua próxima experiência</span><h3>EVO Open —<br>Duplas & Conexões</h3><div class="summary-meta"><span>${icon('calendar-blank')}28 de novembro de 2026</span><span>${icon('clock')}Das 08h às 14h</span><span>${icon('map-pin')}EVO Hípica · Brasília</span><span>${icon('user')}1 participante</span></div><div class="summary-price"><span>Total da inscrição</span><strong>R$ 180,00</strong></div></div></div><p class="summary-caption">${icon('shield-check')} Seus dados e a sua experiência importam.</p></aside>`;}
function steps(payment=false){return `<div class="steps" aria-label="Etapas da inscrição ilustrativa"><span class="step ${payment?'done':'active'}"><b>${payment?icon('check'):'1'}</b>Seus dados</span><span class="step-line"></span><span class="step ${payment?'active':''}"><b>2</b>Pagamento</span><span class="step-line"></span><span class="step"><b>3</b>Confirmação</span></div>`;}
function registration(payment=false){return `${header()}<main id="conteudo" class="container view-enter">${breadcrumbs([{text:'EVO Open',href:'evento'},{text:'Inscrição'}])}<div class="checkout-layout"><div><div class="page-heading" style="padding-top:3px"><span class="eyebrow section-eyebrow">Falta pouco para o próximo jogo</span><h1>${payment?'Seu próximo passo.':'Vamos viver esse encontro?'}</h1><p>${payment?'Confira o resumo antes de seguir para o pagamento.':'Confira seus dados e os detalhes da sua experiência.'}</p></div><section class="checkout-content">${steps(payment)}${payment?`<h2>Pagamento pelo Asaas</h2><p class="quiet">O pagamento acontece em uma página segura do Asaas. Depois, você acompanha a sua inscrição aqui.</p><div class="payment-logo">${icon('shield-check')}asaas</div><div class="payment-methods"><span class="method">${icon('qr-code')}Pix</span><span class="method">${icon('credit-card')}Cartão</span><span class="method">${icon('barcode')}Boleto</span></div><p class="quiet">As formas disponíveis serão apresentadas pelo Asaas no momento do pagamento.</p><div class="notice">${icon('info')}<span><strong>Após o pagamento</strong><br>Voltar para o site não confirma o pagamento. A inscrição aparecerá como confirmada após a verificação.</span></div><div class="action-row"><a class="text-link" href="${link('inscricao')}">Voltar aos dados</a><button type="button" class="btn primary" data-demo="Esta tela é uma prévia visual. Nenhum link Asaas foi conectado e nenhuma cobrança será feita.">Continuar para o Asaas ${icon('lock-simple')}</button></div><p class="design-caption">${icon('ruler')}Etapa ilustrativa · Nenhum pagamento disponível nesta prévia.</p>`:`<h2>Quem vai entrar em quadra?</h2><p class="quiet">Os dados virão da sua conta existente na EVO.</p><div class="identity-example">${icon('user-circle-check')}<div><strong>Conta EVO · exemplo visual</strong><span>Assim os dados aparecerão após conectar sua conta existente. Não há sessão EVO ativa nesta prévia.</span></div></div><div class="form-grid"><div class="field full"><label for="nome">Nome do participante</label><input id="nome" name="nome" value="Marina Oliveira" readonly autocomplete="off"><small>Dados fictícios para demonstrar a tela.</small></div><div class="field full"><label for="email">E-mail de contato</label><input id="email" type="email" value="marina@example.com" readonly autocomplete="off"></div></div><label class="checkbox-line"><input type="checkbox" checked><span>Li as informações do evento e estou de acordo com as condições de participação apresentadas.</span></label><div class="action-row"><span class="tiny">${icon('shield-check')}Seus dados ficam protegidos</span><a class="btn primary" href="${link('pagamento')}">Ver etapa de pagamento</a></div>`}</section></div>${summary()}</div></main>${footer()}`;}
function waitlist(){return `${header()}<main id="conteudo" class="container view-enter">${breadcrumbs([{text:'Sunset na quadra'},{text:'Lista de espera'}])}<section class="wait-card"><div class="wait-symbol">${icon('hourglass-medium')}</div><span class="eyebrow" style="color:#c7a8ed">Ainda pode dar jogo</span><h1>Os bons encontros<br>valem a espera.</h1><p>As vagas do <strong>Sunset na quadra</strong> estão preenchidas. Esta é a prévia de como você acompanhará a lista de espera.</p><div class="wait-position"><span>Sua posição na lista<br><span class="tiny">Exemplo ilustrativo</span></span><strong>03</strong></div><div class="notice" style="text-align:left">${icon('bell-ringing')}<span>Quando surgir uma vaga, você receberá as orientações para continuar. <strong>Nenhum pagamento é necessário enquanto estiver na lista.</strong></span></div><a class="btn secondary" href="${link('minhas')}">Ver minhas inscrições</a><p class="tiny muted" style="margin-top:20px">A lista de espera não garante a participação no evento.</p></section></main>${footer()}`;}
function myEvents(){return `${header()}<main id="conteudo" class="container view-enter"><div class="page-heading"><span class="eyebrow section-eyebrow">Sua agenda EVO</span><h1>Os próximos momentos<br>já têm lugar aqui.</h1><p>Veja como você acompanhará suas inscrições, pagamentos e listas de espera.</p></div><div class="tabs" style="margin-bottom:24px"><button class="tab active" type="button" ${demo}>Próximas experiências <span style="color:#89b89b">2</span></button><button class="tab" type="button" ${demo}>Anteriores</button></div><div class="ticket-list"><article class="ticket"><img src="${picture}" alt="Quadra ilustrativa do EVO Open"><div class="ticket-main"><span class="pill green">${icon('check-circle')}Confirmada · exemplo</span><h2>EVO Open — Duplas & Conexões</h2><div class="summary-meta"><span>${icon('calendar-blank')}28 nov · 08h às 14h</span><span>${icon('map-pin')}EVO Hípica</span></div><p class="tiny muted" style="margin:17px 0 0">Participante: Marina Oliveira · dados fictícios</p></div><div class="ticket-side">${icon('ticket')}<span class="ticket-code">INSCRIÇÃO ILUSTRATIVA<br>EVO-EXEMPLO-001</span><a class="btn ghost small" href="${link('evento')}">Ver evento</a></div></article><article class="ticket"><img src="${picture}" alt="Imagem ilustrativa do Sunset na quadra" style="filter:sepia(.4) hue-rotate(328deg) brightness(.7)"><div class="ticket-main"><span class="pill purple">${icon('hourglass-medium')}Lista de espera · exemplo</span><h2>Sunset na quadra</h2><div class="summary-meta"><span>${icon('calendar-blank')}5 dez · 16h às 20h</span><span>${icon('map-pin')}EVO Noroeste</span></div><p class="tiny muted" style="margin:17px 0 0">Posição ilustrativa: 03 · sem pagamento</p></div><div class="ticket-side">${icon('hourglass-medium')}<span class="ticket-code">A GENTE AVISA<br>Quando uma vaga aparecer.</span><a class="btn ghost small" href="${link('espera')}">Acompanhar</a></div></article></div><div class="empty-note">${icon('sparkle')}<span>Sempre tem um novo encontro esperando por você.<br><a href="${link('catalogo')}" style="color:#96dbaa">Explore as próximas experiências da EVO.</a></span></div></main>${footer()}`;}
function adminNav(){return `<aside class="sidebar">${brand(true)}<div><p class="sidebar-label">Espaço de gestão</p><nav class="side-nav" aria-label="Administração"><a href="${link('admin')}">${icon('squares-four')}Visão geral</a><a href="${link('admin')}" class="${view==='admin'||view==='editor'?'active':''}">${icon('calendar-blank')}Eventos <span class="nav-count">4</span></a><a href="${link('participantes')}" class="${view==='participantes'?'active':''}">${icon('users')}Inscrições</a><a href="#" data-demo="Agendamento ilustrativo. As datas podem ser avaliadas no formulário Criar evento.">${icon('clock-countdown')}Agendamentos</a></nav></div><div><p class="sidebar-label">Organização</p><nav class="side-nav" aria-label="Organização"><a href="#" ${demo}>${icon('map-pin')}Unidades</a><a href="#" ${demo}>${icon('gear-six')}Configurações</a></nav></div><div class="sidebar-bottom"><div class="sidebar-person"><span class="avatar purple">JC</span><div><strong>João · exemplo</strong><span>Equipe EVO</span></div></div><a href="${link('catalogo')}" class="text-link">${icon('globe-simple')}Voltar ao site</a></div></aside>`;}
function adminShell(body,section='Eventos',editor=false){return `${preview()}<div class="admin-shell">${adminNav()}<div class="admin-main"><header class="admin-topbar"><div class="admin-mobile-brand">${brand(true)}</div><div class="breadcrumb-inline"><span>Gestão</span>${icon('caret-right')}<span style="color:#d3dce6">${section}</span></div><div class="right"><span class="pill gray">Dados de demonstração</span><a href="${link('catalogo')}" class="text-link" aria-label="Voltar ao site de eventos">${icon('globe-simple')}</a>${icon('bell')}<span class="avatar purple" aria-label="Perfil ilustrativo da equipe">JC</span></div></header><main id="conteudo" class="admin-content view-enter"><nav class="admin-mobile-nav" aria-label="Seções de administração"><a href="${link('admin')}" class="${view==='admin'?'active':''}">${icon('calendar-blank')}Eventos</a><a href="${link('participantes')}" class="${view==='participantes'?'active':''}">${icon('users')}Inscrições</a><a href="${link('catalogo')}" aria-label="Voltar ao site">${icon('globe-simple')}</a></nav>${body}</main>${editor?`<div class="editor-actions"><span>${icon('cloud-slash')}Prévia visual · sem salvamento</span><div><button type="button" class="btn ghost" ${demo}>Salvar rascunho</button><button type="button" class="btn primary" data-demo="Publicação apenas ilustrativa. Nenhum evento foi criado ou publicado.">Publicar evento</button></div></div>`:''}</div></div>`;}
function stats(){return `<div class="stat-grid"><article class="stat-card"><div class="stat-top">Eventos publicados ${icon('calendar-check')}</div><strong>03</strong><small class="green">Prontos para novos encontros</small></article><article class="stat-card"><div class="stat-top">Inscrições confirmadas ${icon('users')}</div><strong>84</strong><small>Nos eventos da agenda</small></article><article class="stat-card"><div class="stat-top">Aguardando pagamento ${icon('credit-card')}</div><strong>12</strong><small>Em etapa de verificação</small></article><article class="stat-card purple"><div class="stat-top">Na lista de espera ${icon('hourglass-medium')}</div><strong>07</strong><small>Esperando o próximo lugar</small></article></div>`;}
function adminRow(event,index){const ratios=[['40','48',83],['12','24',50],['32','32',100]];const ratio=ratios[index];return `<tr><td><div class="table-event"><img src="${picture}" alt="" style="${index===2?'filter:sepia(.4) hue-rotate(328deg)':''}"><div><strong>${index===0?`<a href="${link('participantes')}">${event.title}</a>`:event.title}</strong><small>${icon('map-pin')}${event.place.split(' · ')[0]}</small></div></div></td><td class="table-date">${event.day} ${event.month.toLowerCase()} 2026<br><small>${event.time}</small></td><td><span class="pill ${event.available?'green':'purple'}">${event.available?'Publicado':'Esgotado'}</span></td><td><span class="progress-count">${ratio[0]} <span>/ ${ratio[1]}</span></span><div class="progress ${index===2?'purple':''}"><span style="width:${ratio[2]}%"></span></div></td><td style="text-align:center">${index===2?'7':'0'}</td><td><button type="button" class="table-action" data-demo="Edição ilustrativa. Use Criar evento para explorar o design do formulário." aria-label="Edição ilustrativa de ${event.title}">${icon('pencil-simple')}</button></td></tr>`;}
function dashboard(){return adminShell(`<div class="admin-page-head"><div><h1>Seus eventos.</h1><p>Boas experiências começam com uma boa organização.</p></div><a href="${link('editor')}" class="btn primary">${icon('plus')}Criar <span class="long">evento</span></a></div>${stats()}<section class="panel"><div class="panel-head"><div><h2>A agenda da EVO</h2><p>Gerencie cada encontro, do primeiro convite ao último ponto.</p></div><button type="button" class="text-link" style="background:none;border:0" ${demo}>${icon('sliders-horizontal')}Filtros</button></div><div class="panel-toolbar"><div class="tabs"><button type="button" class="tab active" ${demo}>Todos <span>4</span></button><button type="button" class="tab" ${demo}>Publicados <span>3</span></button><button type="button" class="tab" ${demo}>Agendados <span>1</span></button></div><button class="filter-box" type="button" ${demo}>${icon('magnifying-glass')}Buscar evento</button></div><p class="table-hint">${icon('arrows-left-right')}Deslize a tabela para ver mais detalhes</p><div class="table-scroll" role="region" aria-label="Eventos de exemplo, deslize para ver todas as colunas" tabindex="0"><table><thead><tr><th>Evento</th><th>Data e horário</th><th>Status</th><th>Confirmados</th><th>Espera</th><th><span class="sr-only">Editar</span></th></tr></thead><tbody>${events.map((event,index)=>adminRow(event,index)).join('')}<tr><td><div class="table-event"><div style="width:51px;height:51px;display:grid;place-items:center;border:1px solid #3e4c62;border-radius:7px;background:#24283b;color:#b4a0d2">${icon('tennis-ball')}</div><div><strong>Kids Day — Pequenos grandes jogos</strong><small>${icon('map-pin')}EVO Hípica</small></div></div></td><td class="table-date">12 dez 2026<br><small>09h às 12h</small></td><td><span class="pill amber">${icon('clock')}Agendado</span></td><td><span class="progress-count">0 <span>/ 30</span></span><div class="progress"><span style="width:0"></span></div></td><td style="text-align:center">—</td><td><button type="button" class="table-action" data-demo="Edição ilustrativa. Use Criar evento para explorar o design do formulário." aria-label="Edição ilustrativa do Kids Day">${icon('pencil-simple')}</button></td></tr></tbody></table></div><div class="table-footer"><span>Exibindo 4 eventos ilustrativos</span><div class="pagination"><button type="button" ${demo} aria-label="Página anterior">${icon('caret-left')}</button><button type="button" class="active" ${demo} aria-label="Página 1">1</button><button type="button" ${demo} aria-label="Próxima página">${icon('caret-right')}</button></div></div></section><div class="admin-bottom"><section class="mini-panel"><h3>${icon('clock-countdown')}Próximos na agenda</h3><div class="activity"><div class="date-mini"><strong>28</strong><span>NOV</span></div><div><strong>EVO Open — Duplas & Conexões</strong><span>08h · EVO Hípica · 40 confirmados</span></div></div><div class="activity"><div class="date-mini"><strong>29</strong><span>NOV</span></div><div><strong>Clínica de saque & devolução</strong><span>09h · EVO Lago Sul · 12 confirmados</span></div></div></section><section class="mini-panel"><h3>${icon('pulse')}Um olhar sobre os eventos</h3><div class="activity">${icon('users')}<div><strong>84 pessoas com encontro marcado.</strong><span>Nas três experiências publicadas de exemplo.</span></div></div><div class="activity">${icon('calendar-blank')}<div><strong>Kids Day está preparado para publicação.</strong><span>Exemplo de agendamento · 23 nov, 09h.</span></div></div></section></div><p class="design-caption">${icon('ruler')}Todos os números e eventos são fictícios. Esta é uma prévia do painel, sem ações de gestão reais.</p>`);}
function field(label,id,value,type='text',full=false,note=''){return `<div class="field ${full?'full':''}"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${value}" autocomplete="off">${note?`<small>${note}</small>`:''}</div>`;}
function editor(){return adminShell(`<div class="admin-page-head"><div><a class="text-link" href="${link('admin')}" style="min-height:27px;font-size:.72rem;margin-bottom:13px">${icon('caret-left')}Todos os eventos</a><h1>Um novo encontro.</h1><p>Cuide dos detalhes. A experiência começa aqui.</p></div><span class="pill gray" style="margin-top:7px">Rascunho · exemplo</span></div><div class="editor-layout"><form id="visual-editor"><section class="panel form-panel"><h2>O evento</h2><p class="quiet">Dê identidade à próxima experiência da EVO.</p><div class="upload-area"><img src="${picture}" alt="Prévia ilustrativa de capa do evento"><div><strong>Capa do evento</strong><span>Uma boa imagem já convida a participar.<br>JPG ou PNG · recomendado 1600 × 900 px</span><button type="button" ${demo}>Escolher outra imagem</button></div></div><div class="form-grid">${field('Título do evento','titulo','Clínica de saque & devolução','text',true)}<div class="field"><label for="categoria">Categoria</label><select id="categoria"><option>Clínica</option><option>Torneio</option><option>Experiência</option></select><span class="select-chevron" aria-hidden="true">${icon('caret-down')}</span></div><div class="field"><label for="unidade">Unidade</label><select id="unidade"><option>EVO Lago Sul</option><option>EVO Hípica</option><option>EVO Noroeste</option></select><span class="select-chevron" aria-hidden="true">${icon('caret-down')}</span></div><div class="field full"><label for="descricao">Sobre a experiência</label><textarea id="descricao">Pequenos ajustes, grandes pontos. Uma manhã dedicada a evoluir o saque e a devolução, com orientação da equipe EVO e exercícios para colocar em prática no seu próximo jogo.</textarea><small>Conte o que vai acontecer e o que o participante pode esperar.</small></div></div></section><section class="panel form-panel"><h2>Data, horário e vagas</h2><p class="quiet">Defina quando o encontro acontece e quem pode fazer parte.</p><div class="form-grid">${field('Data de início','inicio-data','2026-11-29','date')}${field('Horário de início','inicio-hora','09:00','time')}${field('Data de encerramento','fim-data','2026-11-29','date')}${field('Horário de encerramento','fim-hora','12:00','time')}${field('Quantidade de vagas','vagas','24','number')}${field('Valor por participante (R$)','valor','90,00','text')}</div><label class="checkbox-line" style="margin-bottom:0"><input type="checkbox" checked><span>Ativar lista de espera quando todas as vagas forem preenchidas.</span></label></section><section class="panel form-panel"><h2>Inscrições e publicação</h2><p class="quiet">Prepare tudo agora e escolha quando abrir as portas.</p><div class="form-grid">${field('Abertura das inscrições','abertura','2026-11-20T09:00','datetime-local',true)}${field('Encerramento das inscrições','encerramento','2026-11-28T18:00','datetime-local',true)}${field('Publicar em','publicacao','2026-11-20T09:00','datetime-local',true,'Datas e horários de Brasília (UTC−3).')}</div></section><section class="panel form-panel"><h2>Pagamento</h2><p class="quiet">A experiência de pagamento será conectada ao Asaas.</p><div class="field"><label for="asaas">Link de pagamento Asaas</label><input id="asaas" type="url" placeholder="Link será configurado na etapa de integração" readonly><small>Nenhum link ou cobrança está ativo nesta prévia.</small></div><div class="notice">${icon('shield-check')}<span>O limite de vagas e a confirmação do pagamento serão validados na etapa de funcionalidades. Aqui você está avaliando apenas o design.</span></div></section></form><aside class="editor-preview"><span class="eyebrow">${icon('eye')}Prévia ilustrativa do cartão</span>${eventCard(events[1],true)}<p class="editor-tip">${icon('lightbulb')}Escolha uma capa que mostre a energia do encontro. Prefira imagens com o assunto principal no centro.</p><p class="editor-tip">${icon('ruler')}As edições de exemplo não são salvas nem atualizam este cartão.</p></aside></div>`,`Novo evento`,true);}
